import{_ as t,o,c as a,a2 as r}from"./chunks/framework.iWwp2X7T.js";const h=JSON.parse('{"title":"MCP tools","description":"Mobile Inspector development documentation · MCP tools","frontmatter":{"title":"MCP tools","description":"Mobile Inspector development documentation · MCP tools"},"headers":[],"relativePath":"en/reference/mcp.md","filePath":"en/reference/mcp.md"}'),n={name:"en/reference/mcp.md"};function s(i,e,d,c,l,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="mcp-tools" tabindex="-1">MCP tools <a class="header-anchor" href="#mcp-tools" aria-label="Permalink to &quot;MCP tools&quot;">​</a></h1><p>Exactly five read-only stdio tools share the existing project-scoped collector. There is no tool to change source, run shell, choose another root, start capture or repair a client.</p><table tabindex="0"><thead><tr><th>Tool</th><th>Read scope</th></tr></thead><tbody><tr><td><code>list_sessions</code></td><td>Available sessions in the bound project</td></tr><tr><td><code>get_request_trace</code></td><td>One session/generation, optionally one request</td></tr><tr><td><code>get_related_logs</code></td><td>Session/request or incident log scope</td></tr><tr><td><code>list_incidents</code></td><td>Bounded candidate observations</td></tr><tr><td><code>get_incident</code></td><td>One retained incident with shared diagnosis status</td></tr></tbody></table><h2 id="safe-pagination" tabindex="-1">Safe pagination <a class="header-anchor" href="#safe-pagination" aria-label="Permalink to &quot;Safe pagination&quot;">​</a></h2><p>List first; pass its <code>sessionId</code> and <code>instanceGeneration</code> unchanged. Optional request selector narrows trace/log results. Default limit 50, maximum 200; byte limits can return fewer. Continue opaque <code>nextCursor</code> with the same selectors, generation, scope and limit until null. Cursors bind project, recording, revision and high-water mark. Expired, stale or malformed cursors reject.</p><p>Results expose <code>schemaVersion</code>, project/generation/revision, items, next cursor, completeness and gaps. <code>complete: false</code> cannot be interpreted as a full trace. Clear/revoke/expiry invalidates prior reads. Summary-only is the default; approved-body reads require a live per-session grant on every read. Authentication bodies, credentials, binary and audio remain excluded.</p><p>MCP protocol roundtrip, installed packaging and authenticated host interoperability are different evidence levels. New tools may not share an older host&#39;s acceptance scope. See <a href="./../integrations/codex">Codex setup</a> and <a href="./incidents">incidents</a>.</p>',7)])])}const m=t(n,[["render",s]]);export{h as __pageData,m as default};
